__global__ void matrix_mul_kernel(const float* A, const float* B, float* C, int N) {
    // TILE_DIM should be a multiple of WARP_SIZE for optimal performance
    // For example, 32 or 16
    const int TILE_DIM = 32; 

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A into shared memory
        int a_row_global = row;
        int a_col_global = t * TILE_DIM + threadIdx.x;
        if (a_row_global < N && a_col_global < N) {
            As[threadIdx.y][threadIdx.x] = A[a_row_global * N + a_col_global];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row_global = t * TILE_DIM + threadIdx.y;
        int b_col_global = col;
        if (b_row_global < N && b_col_global < N) {
